Import ListNotations.
Open Scope Z_scope.
Set Warnings "-notation-for-abbreviation".
Local Ltac Z.euclidean_division_equations_cleanup ::= idtac.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.

Section CE.
  Variables (sp gp tp : word) (F : bvmap 5 word) (fc : bv 32).
  Variables (x1 x8 x9 x13 x21 x22 x25 x29 : word) (x6 x15 x23 : word).
  Variables (m : fmem) (DT SY b e nb tl : Z) (sorted : list (option Z)) (js jt : list byte) (ncells : nat).
  Variable POST : machine_state -> Prop.
  Hypothesis HJT : length jt = (4 * ncells)%nat.
  Hypothesis HJS : length js = length sorted.
  Hypothesis HLS : length sorted = 256%nat.
  Hypothesis HSYR : forall i v, nth i sorted None = Some v -> 0 <= v < 256.
  Hypothesis HDT : 0 < DT /\ DT + 4 + 4 * Z.of_nat ncells <= 2^47.
  Hypothesis DJ : DT + 4 + 4 * Z.of_nat ncells <= SY \/ SY + 256 <= DT + 4.
  Hypothesis HSY : 0 < SY /\ SY + 256 <= 2^47.
  Hypothesis HNB : 1 <= nb <= 12.
  Hypothesis HTL : 4 <= tl - nb <= 11.
  Hypothesis HBE : 0 <= b <= e /\ e <= 256.
  Notation INV m1 dt := (x2f_inv m m1 DT SY js jt sorted ncells dt).
  Notation D := (nb * 65536 + 16777216).
  Notation LEN := (2 ^ (tl - nb)).
  Notation UU sym := (Z.lor (Z.lor D sym ≪ 32 mod 18446744073709551616) (Z.lor D sym)).

  (* [comment removed for export] *)
  Lemma c1e_chunks : forall n sym c s u dt1 v m1 dtR (x5 x7 x28 : word),
    c = build_x2 sym nb 0 1 -> 0 <= sym < 256 ->
    store_run (8 * n) dt1 v c = Ok dtR -> 0 <= v -> v + 8 * Z.of_nat n = u + LEN -> (0 < n)%nat -> INV m1 dt1 ->
    (forall m2 (y5 y7 y28 : word), INV m2 dtR ->
       evt psegs POST (MS (mkR x1 sp gp tp y5 x6 y7 x8 x9 (Z_to_bv 64 (SY + s)) (Z_to_bv 64 D)
                               (Z_to_bv 64 (DT + 4 + 4 * (u + LEN))) x13 (Z_to_bv 64 (4 * LEN)) x15
                               (Z_to_bv 64 (DT + 4 + 4 * (u + LEN))) (Z_to_bv 64 (UU sym)) (Z_to_bv 64 2) (Z_to_bv 64 4)
                               (Z_to_bv 64 8) x21 x22 x23 (Z_to_bv 64 SY) x25 (Z_to_bv 64 (SY + e)) (Z_to_bv 64 b) y28 x29
                               (Z_to_bv 64 1) (Z_to_bv 64 3))
                          F (Z_to_bv 64 0x143ac) fc None m2 (seg_rom psegs))) ->
    evt psegs POST (MS (mkR x1 sp gp tp x5 x6 x7 x8 x9 (Z_to_bv 64 (SY + s)) (Z_to_bv 64 D)
                            (Z_to_bv 64 (DT + 4 + 4 * (u + LEN))) x13 (Z_to_bv 64 (4 * LEN)) x15
                            (Z_to_bv 64 (DT + 4 + 4 * v)) (Z_to_bv 64 (UU sym)) (Z_to_bv 64 2) (Z_to_bv 64 4)
                            (Z_to_bv 64 8) x21 x22 x23 (Z_to_bv 64 SY) x25 (Z_to_bv 64 (SY + e)) (Z_to_bv 64 b) x28 x29
                            (Z_to_bv 64 1) (Z_to_bv 64 3))
